// ─── File: src/main/java/com/bank/portfolio/service/SymbolPortfolioService.java ───
package com.bank.portfolio.service;

import com.bank.portfolio.dto.PortfolioReport;
import com.bank.portfolio.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
@Slf4j
public class SymbolPortfolioService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "SAV2001", "RELIANCE", "BUY",  new BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-002", "SAV2001", "TCS",      "BUY",  new BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-003", "SAV2001", "HDFC",     "SELL", new BigDecimal("330150"), "SETTLED"),
        new Trade("TRD-004", "SAV2001", "INFY",     "BUY",  new BigDecimal("222037"), "SETTLED"),
        new Trade("TRD-005", "SAV2001", "RELIANCE", "SELL", new BigDecimal("123750"), "SETTLED"),
        new Trade("TRD-006", "SAV2001", "TCS",      "BUY",  new BigDecimal("88750"),  "SETTLED")
    );

    public PortfolioReport buildPortfolio(String accountId) {
        List<Trade> accountTrades = trades.stream()
            .filter(t -> t.accountId().equals(accountId))
            .toList();

        // ═══ 1. THE CRASH: toMap without merge → duplicate key! ═══
        String duplicateError;
        try {
            accountTrades.stream()
                .collect(Collectors.toMap(Trade::symbol, Trade::amount));
            duplicateError = "No error (all keys unique)";
        } catch (IllegalStateException e) {
            duplicateError = " " + e.getMessage();
            log.error("Duplicate key crash: {}", e.getMessage());
        }

        // ═══ 2. SUM: merge with BigDecimal::add ═══
        Map<String, BigDecimal> sumBySymbol = accountTrades.stream()
            .collect(Collectors.toMap(Trade::symbol, Trade::amount,
                BigDecimal::add));
        // RELIANCE: 245050 + 123750 = 368800
        // TCS: 176000 + 88750 = 264750
        log.info("Sum by symbol: {}", sumBySymbol);

        // ═══ 3. FIRST: keep existing value ═══
        Map<String, BigDecimal> firstBySymbol = accountTrades.stream()
            .collect(Collectors.toMap(Trade::symbol, Trade::amount,
                (existing, incoming) -> existing));
        // RELIANCE: 245050 (first trade kept)

        // ═══ 4. MAX: keep larger value ═══
        Map<String, BigDecimal> maxBySymbol = accountTrades.stream()
            .collect(Collectors.toMap(Trade::symbol, Trade::amount,
                BigDecimal::max));
        // RELIANCE: 245050 (larger of 245050 and 123750)

        // ═══ 5. ORDERED: LinkedHashMap preserves insertion order ═══
        Map<String, BigDecimal> orderedBySymbol = accountTrades.stream()
            .collect(Collectors.toMap(Trade::symbol, Trade::amount,
                BigDecimal::add, LinkedHashMap::new));
        // Keys iterate in order: RELIANCE, TCS, HDFC, INFY (first-seen order)

        // ═══ 6. SORTED: TreeMap sorts keys alphabetically ═══
        Map<String, BigDecimal> sortedBySymbol = accountTrades.stream()
            .collect(Collectors.toMap(Trade::symbol, Trade::amount,
                BigDecimal::add, TreeMap::new));
        // Keys iterate alphabetically: HDFC, INFY, RELIANCE, TCS

        // ═══ 7. ENTITY LOOKUP: tradeId → tradeId + symbol (using identity) ═══
        Map<String, String> tradeLookup = accountTrades.stream()
            .collect(Collectors.toMap(Trade::tradeId,
                t -> t.symbol() + " Rs." + t.amount(),
                (a, b) -> a));  // merge for safety even though tradeId is unique

        return new PortfolioReport(accountId, sumBySymbol, firstBySymbol,
            maxBySymbol, orderedBySymbol, sortedBySymbol, duplicateError, tradeLookup);
    }
}
```

