// ─── File: src/test/java/com/bank/portfolio/service/ToMapCollectorTest.java ───
package com.bank.portfolio.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.Function;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class ToMapCollectorTest {

    @Test
    void toMapThrowsOnDuplicateKeys() {
        assertThatThrownBy(() ->
            Stream.of("A", "B", "A")
                .collect(Collectors.toMap(s -> s, String::length)))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("Duplicate key");
    }

    @Test
    void toMapWithMergeKeepsExisting() {
        Map<String, Integer> result = Stream.of("RELIANCE", "TCS", "RELIANCE")
            .collect(Collectors.toMap(s -> s, String::length,
                (existing, incoming) -> existing));
        assertThat(result).containsEntry("RELIANCE", 8);  // first value kept
    }

    @Test
    void toMapWithMergeSumsValues() {
        Map<String, BigDecimal> result = Stream.of(
            Map.entry("RELIANCE", new BigDecimal("100")),
            Map.entry("TCS", new BigDecimal("200")),
            Map.entry("RELIANCE", new BigDecimal("50")))
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue,
                BigDecimal::add));
        assertThat(result.get("RELIANCE")).isEqualByComparingTo("150");  // 100 + 50
        assertThat(result.get("TCS")).isEqualByComparingTo("200");
    }

    @Test
    void toMapWithLinkedHashMapPreservesOrder() {
        Map<String, Integer> result = Stream.of("C", "A", "B")
            .collect(Collectors.toMap(s -> s, String::length,
                (a, b) -> a, LinkedHashMap::new));
        assertThat(new ArrayList<>(result.keySet())).containsExactly("C", "A", "B");
    }

    @Test
    void toMapWithTreeMapSortsKeys() {
        Map<String, Integer> result = Stream.of("C", "A", "B")
            .collect(Collectors.toMap(s -> s, String::length,
                (a, b) -> a, TreeMap::new));
        assertThat(new ArrayList<>(result.keySet())).containsExactly("A", "B", "C");
    }

    @Test
    void toMapWithIdentityForLookup() {
        record Trade(String id, String symbol) {}
        var trades = List.of(new Trade("T1", "RELIANCE"), new Trade("T2", "TCS"));

        Map<String, Trade> lookup = trades.stream()
            .collect(Collectors.toMap(Trade::id, Function.identity()));

        assertThat(lookup.get("T1").symbol()).isEqualTo("RELIANCE");
        assertThat(lookup.get("T2").symbol()).isEqualTo("TCS");
    }

    @Test
    void toMapNullValueThrows() {
        // toMap does NOT allow null values!
        assertThatThrownBy(() ->
            Stream.of("A", "B")
                .collect(Collectors.toMap(s -> s, s -> (String) null)))
            .isInstanceOf(NullPointerException.class);
    }

    @Test
    void defaultMapIsHashMap() {
        Map<String, Integer> result = Stream.of("A")
            .collect(Collectors.toMap(s -> s, String::length));
        assertThat(result).isInstanceOf(HashMap.class);
    }
}
